using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Constants;

internal sealed class ElementaryExactValuesDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() =>
        DocumentDefinition.Create(ScribeDocument.Create(
            Header(
                "D5/S3/Constants/ElementaryExactValues",
                "The elementary constants have exact forms in the quadratic field generated by square root five."),
            H("Elementary Exact Values"),
            Blocks(
                DocumentBlock.Describe.Theorem(
                    DescribeId.Create("elementary-exact-values"),
                    H("The elementary constants lie in the golden quadratic field"),
                    LeanTheorem(
                        "D5/S3/Constants/ElementaryExactValues.elementary_exact_values"),
                    LatexStatement.Create(
                        @"$$A_F=\kappa=\frac{1}{2\varphi}=\frac{\sqrt{5}-1}{4},\qquad "
                        + @"\overline{h}=-\frac{1}{2},\qquad s_1=\frac{1+\sqrt{5}}{12},\qquad "
                        + @"A_h=\frac{5\sqrt{5}-3}{24},\qquad "
                        + @"E=\frac{137-61\sqrt{5}}{24}.$$"),
                    DescribeProvenance.RepoDerived(),
                    Blocks(
                        Paragraph(Text(
                            "Write A_F for the slope constant kappa. Its defining reciprocal "
                            + "golden-ratio expression rationalizes to (sqrt(5) - 1) / 4. "
                            + "The correction-fiber mean, dimension-reduction coefficient, "
                            + "h-side constant, and elementary shell are already given by "
                            + "their exact expressions in the same quadratic field.")),
                        Paragraph(Text(
                            "The proof unfolds the repository's canonical constant definitions. "
                            + "All clauses except the rationalized form of kappa are definitional; "
                            + "that clause follows by clearing the nonzero golden-ratio denominator "
                            + "and using the identity (sqrt(5))^2 = 5. Thus the theorem is an exact "
                            + "algebraic package and introduces no numerical approximation.")))
                ))));
}
